	private static String renderMask(int mask, int firstBit, String firstName, int secondBit, String secondName,
			int thirdBit, String thirdName, int fourthBit, String fourthName) {
		StringBuilder result = new StringBuilder();
		append(result, mask, firstBit, firstName);
		append(result, mask, secondBit, secondName);
		append(result, mask, thirdBit, thirdName);
		append(result, mask, fourthBit, fourthName);
		return result.length() == 0 ? "NONE" : result.toString();
	}

	private static void append(StringBuilder target, int mask, int bit, String name) {
		if (bit == 0 || (mask & bit) == 0) {
			return;
		}
		if (target.length() > 0) {
			target.append('+');
		}
		target.append(name);
	}

